namespace exgine { namespace {
constexpr GlEnum GL_FRAMEBUFFER=0x8D40,GL_COLOR_ATTACHMENT0=0x8CE0,GL_DEPTH_ATTACHMENT=0x8D00,GL_FRAMEBUFFER_COMPLETE=0x8CD5;
constexpr GlEnum GL_DEPTH_COMPONENT24=0x81A6,GL_DEPTH_COMPONENT16=0x81A5,GL_DEPTH_COMPONENT=0x1902,GL_UNSIGNED_INT=0x1405,GL_UNSIGNED_SHORT=0x1403;
constexpr GlEnum GL_RGBA16F=0x881A,GL_RGBA8=0x8058,GL_RGBA=0x1908,GL_HALF_FLOAT=0x140B,GL_UNSIGNED_BYTE=0x1401;
constexpr GlEnum GL_TEXTURE_2D=0x0DE1,GL_TEXTURE_MIN_FILTER=0x2801,GL_TEXTURE_MAG_FILTER=0x2800,GL_TEXTURE_WRAP_S=0x2802,GL_TEXTURE_WRAP_T=0x2803,GL_TEXTURE_WRAP_R=0x8072;
constexpr GlEnum GL_CLAMP_TO_EDGE=0x812F,GL_LINEAR=0x2601,GL_LINEAR_MIPMAP_LINEAR=0x2703,GL_TEXTURE0=0x84C0,GL_TEXTURE7=GL_TEXTURE0+7,GL_TEXTURE8=GL_TEXTURE0+8;
constexpr GlEnum GL_DEPTH_TEST=0x0B71,GL_BLEND=0x0BE2,GL_LESS=0x0201,GL_TRIANGLES=0x0004,GL_DEPTH_BUFFER_BIT=0x00000100,GL_COLOR_BUFFER_BIT=0x00004000;
constexpr GlEnum GL_VERTEX_SHADER=0x8B31,GL_FRAGMENT_SHADER=0x8B30,GL_COMPILE_STATUS=0x8B81,GL_LINK_STATUS=0x8B82,GL_INFO_LOG_LENGTH=0x8B84;
constexpr GlEnum GL_ARRAY_BUFFER=0x8892,GL_ELEMENT_ARRAY_BUFFER=0x8893,GL_STATIC_DRAW=0x88E4,GL_FLOAT=0x1406,GL_UNSIGNED_INT_INDEX=0x1405;
struct Target{GlUInt fbo=0,color=0,depth=0;int width=0,height=0;bool hdr=false;};
struct ShadowMesh{GlUInt vao=0,vb=0,ib=0;std::size_t index_count=0;bool animated=false;};
struct ProductionState{int width=0,height=0;Target hdr{};std::vector<Target> bloom;Target shadow{};GlUInt atmosphere=0,irradiance=0,specular=0,post_vao=0,bloom_program=0,upsample_program=0,tonemap_program=0;std::unordered_map<std::uint64_t,ShadowMesh> shadow_meshes;bool initialized=false;std::string capability="GLES 3.1 baseline";};
std::mutex g_mutex;std::unordered_map<const OpenGLESRenderer*,std::unique_ptr<ProductionState>> g_states;

bool compile(OpenGLESApi&a,GlEnum type,const char*src,GlUInt&out,std::string&e){out=a.CreateShader(type);if(!out){e="glCreateShader failed";return false;}a.ShaderSource(out,1,&src,nullptr);a.CompileShader(out);GlInt ok=0;a.GetShaderiv(out,GL_COMPILE_STATUS,&ok);if(ok)return true;char log[2048]{};GlInt n=0;a.GetShaderInfoLog(out,2047,&n,log);e.assign(log,static_cast<std::size_t>(std::max(0,n)));a.DeleteShader(out);out=0;return false;}
bool link(OpenGLESApi&a,const char*vs,const char*fs,GlUInt&out,std::string&e){GlUInt v=0,f=0;if(!compile(a,GL_VERTEX_SHADER,vs,v,e)||!compile(a,GL_FRAGMENT_SHADER,fs,f,e)){if(v)a.DeleteShader(v);if(f)a.DeleteShader(f);return false;}out=a.CreateProgram();if(!out){a.DeleteShader(v);a.DeleteShader(f);e="glCreateProgram failed";return false;}a.AttachShader(out,v);a.AttachShader(out,f);a.LinkProgram(out);a.DeleteShader(v);a.DeleteShader(f);GlInt ok=0;a.GetProgramiv(out,GL_LINK_STATUS,&ok);if(ok)return true;char log[2048]{};GlInt n=0;a.GetProgramInfoLog(out,2047,&n,log);e.assign(log,static_cast<std::size_t>(std::max(0,n)));a.DeleteProgram(out);out=0;return false;}

void destroy_target(OpenGLESApi&a,Target&t){if(t.fbo&&a.DeleteFramebuffers)a.DeleteFramebuffers(1,&t.fbo);if(t.color&&a.DeleteTextures)a.DeleteTextures(1,&t.color);if(t.depth&&a.DeleteTextures)a.DeleteTextures(1,&t.depth);t={};}

bool create_color(OpenGLESApi&a,int w,int h,Target&t,bool with_depth,std::string&e){destroy_target(a,t);t.width=w;t.height=h;t.hdr=true;a.GenTextures(1,&t.color);a.BindTexture(GL_TEXTURE_2D,t.color);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_RGBA16F,w,h,0,GL_RGBA,GL_HALF_FLOAT,nullptr);a.GenFramebuffers(1,&t.fbo);a.BindFramebuffer(GL_FRAMEBUFFER,t.fbo);a.FramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,t.color,0);if(with_depth){a.GenTextures(1,&t.depth);a.BindTexture(GL_TEXTURE_2D,t.depth);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_DEPTH_COMPONENT24,w,h,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT,nullptr);a.FramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,t.depth,0);}if(a.CheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE)return true;destroy_target(a,t);return false;}
bool create_color_fallback(OpenGLESApi&a,int w,int h,Target&t,std::string&e){if(create_color(a,w,h,t,true,e))return true;destroy_target(a,t);t.width=w;t.height=h;t.hdr=false;a.GenTextures(1,&t.color);a.BindTexture(GL_TEXTURE_2D,t.color);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);a.GenFramebuffers(1,&t.fbo);a.BindFramebuffer(GL_FRAMEBUFFER,t.fbo);a.FramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,t.color,0);if(a.CheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE)return true;e="no supported HDR/LDR color framebuffer format";destroy_target(a,t);return false;}
bool create_shadow(OpenGLESApi&a,int size,Target&t,std::string&e){destroy_target(a,t);t.width=t.height=size;a.GenTextures(1,&t.depth);a.BindTexture(GL_TEXTURE_2D,t.depth);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_DEPTH_COMPONENT24,size,size,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_INT,nullptr);a.GenFramebuffers(1,&t.fbo);a.BindFramebuffer(GL_FRAMEBUFFER,t.fbo);a.FramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,t.depth,0);if(a.CheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE)return true;destroy_target(a,t);a.GenTextures(1,&t.depth);a.BindTexture(GL_TEXTURE_2D,t.depth);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_DEPTH_COMPONENT16,size,size,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_SHORT,nullptr);a.GenFramebuffers(1,&t.fbo);a.BindFramebuffer(GL_FRAMEBUFFER,t.fbo);a.FramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,t.depth,0);if(a.CheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE)return true;e="no supported depth texture format";destroy_target(a,t);return false;}

std::vector<unsigned char> environment_rgba(int w,int h,const AtmosphereSettings&s,float roughness,bool irradiance){std::vector<unsigned char> out(static_cast<std::size_t>(w*h*4));const Vec3 sun=normalize(Vec3{.35f,.8f,.25f});for(int y=0;y<h;++y){for(int x=0;x<w;++x){float phi=(float(x)+.5f)/float(w)*6.28318530718f;float theta=(float(y)+.5f)/float(h)*3.14159265359f;Vec3 d{std::sin(theta)*std::cos(phi),std::cos(theta),std::sin(theta)*std::sin(phi)};Color3 c=evaluate_sky(s,d,sun);if(irradiance){Color3 acc{};constexpr int taps=8;for(int k=0;k<taps;++k){float a=6.2831853f*float(k)/taps;Vec3 q{d.x*std::cos(.35f)+std::sin(.35f)*std::cos(a),d.y*std::cos(.35f)+std::sin(.35f)*std::sin(a),d.z};acc.r+=evaluate_sky(s,normalize(q),sun).r;acc.g+=evaluate_sky(s,normalize(q),sun).g;acc.b+=evaluate_sky(s,normalize(q),sun).b;}c={acc.r/taps,acc.g/taps,acc.b/taps};}else if(roughness>0.f){float lift=1.f-.35f*roughness;c.r*=lift;c.g*=lift;c.b*=lift;}const std::size_t i=static_cast<std::size_t>((y*w+x)*4);out[i]=static_cast<unsigned char>(std::clamp(c.r,0.f,1.f)*255.f);out[i+1]=static_cast<unsigned char>(std::clamp(c.g,0.f,1.f)*255.f);out[i+2]=static_cast<unsigned char>(std::clamp(c.b,0.f,1.f)*255.f);out[i+3]=255;}}return out;}

bool ensure_texture(OpenGLESApi&a,GlUInt&tex,int w,int h,const std::vector<unsigned char>&pixels,std::string&e){if(tex&&a.DeleteTextures)a.DeleteTextures(1,&tex);a.GenTextures(1,&tex);a.BindTexture(GL_TEXTURE_2D,tex);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);a.TexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);a.TexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());if(a.GenerateMipmap)a.GenerateMipmap(GL_TEXTURE_2D);return tex!=0;}

const char* post_vs=R"GLSL(#version 310 es
precision highp float;void main(){const vec2 p[3]=vec2[3](vec2(-1,-1),vec2(3,-1),vec2(-1,3));gl_Position=vec4(p[gl_VertexID],0,1);} )GLSL";
const char* down_fs=R"GLSL(#version 310 es
precision highp float;uniform sampler2D u_source;uniform vec2 u_texel;uniform float u_threshold;uniform float u_knee;layout(location=0)out vec4 o;void main(){vec2 uv=gl_FragCoord.xy*u_texel;vec3 c=(texture(u_source,uv+u_texel*vec2(-.5,-.5)).rgb+texture(u_source,uv+u_texel*vec2(.5,-.5)).rgb+texture(u_source,uv+u_texel*vec2(-.5,.5)).rgb+texture(u_source,uv+u_texel*vec2(.5,.5)).rgb)*.25;float l=max(max(c.r,c.g),c.b),k=max(u_knee,.0001),w=clamp((l-u_threshold+k)/(2.*k),0.,1.);o=vec4(c*w*w,1);} )GLSL";
const char* up_fs=R"GLSL(#version 310 es
precision highp float;uniform sampler2D u_source;uniform sampler2D u_bloom;uniform vec2 u_texel;layout(location=0)out vec4 o;void main(){vec2 uv=gl_FragCoord.xy*u_texel;vec3 s=texture(u_source,uv).rgb;vec3 b=texture(u_bloom,uv).rgb;o=vec4(s+b,1);} )GLSL";
const char* tone_fs=R"GLSL(#version 310 es
precision highp float;uniform sampler2D u_hdr;uniform sampler2D u_bloom;uniform float u_exposure;uniform float u_bloom_intensity;uniform float u_gamma;uniform float u_white_point;layout(location=0)out vec4 o;vec3 aces(vec3 x){const float a=2.51,b=.03,c=2.43,d=.59,e=.14;return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.,1.);}void main(){vec2 uv=gl_FragCoord.xy/vec2(textureSize(u_hdr,0));vec3 h=texture(u_hdr,uv).rgb*exp2(u_exposure),b=texture(u_bloom,uv).rgb*u_bloom_intensity;vec3 m=aces(h+b);m=m*(1.+h/max(u_white_point,.001))/(1.+h);o=vec4(pow(max(m,vec3(0)),vec3(1./max(u_gamma,.1))),1);} )GLSL";

void destroy_programs(OpenGLESApi&a,ProductionState&s){if(a.DeleteProgram){if(s.bloom_program)a.DeleteProgram(s.bloom_program);if(s.upsample_program)a.DeleteProgram(s.upsample_program);if(s.tonemap_program)a.DeleteProgram(s.tonemap_program);}s.bloom_program=s.upsample_program=s.tonemap_program=0;}
void destroy_state(OpenGLESApi&a,ProductionState&s)noexcept{destroy_programs(a,s);if(a.DeleteVertexArrays&&s.post_vao)a.DeleteVertexArrays(1,&s.post_vao);s.post_vao=0;for(auto&[k,m]:s.shadow_meshes){(void)k;if(m.vao)a.DeleteVertexArrays(1,&m.vao);if(m.vb)a.DeleteBuffers(1,&m.vb);if(m.ib)a.DeleteBuffers(1,&m.ib);}s.shadow_meshes.clear();destroy_target(a,s.hdr);for(auto&t:s.bloom)destroy_target(a,t);s.bloom.clear();destroy_target(a,s.shadow);if(a.DeleteTextures){if(s.atmosphere)a.DeleteTextures(1,&s.atmosphere);if(s.irradiance)a.DeleteTextures(1,&s.irradiance);if(s.specular)a.DeleteTextures(1,&s.specular);}s.atmosphere=s.irradiance=s.specular=0;s.initialized=false;}

ProductionState& state_for(OpenGLESRenderer&r){std::lock_guard<std::mutex>lock(g_mutex);auto&ptr=g_states[&r];if(!ptr)ptr=std::make_unique<ProductionState>();return *ptr;}

void configure_material_program(OpenGLESApi&a,GlUInt program,const ShadowSettings&shadow,const ProductionState&s,float ibl){if(!program)return;a.UseProgram(program);auto loc=[&](const char*n){return a.GetUniformLocation(program,n);};if(auto u=loc("u_shadow_map");u>=0)a.Uniform1i(u,7);if(auto u=loc("u_environment_map");u>=0)a.Uniform1i(u,8);if(auto u=loc("u_shadow_bias");u>=0)a.Uniform1f(u,shadow.depth_bias);if(auto u=loc("u_ibl_intensity");u>=0)a.Uniform1f(u,ibl);if(auto u=loc("u_shadow_vp");u>=0)a.UniformMatrix4fv(u,1,0,shadow.cascade[0].view_projection.m.data());}

bool ensure_post(OpenGLESApi&a,ProductionState&s,std::string&e){if(s.post_vao==0)a.GenVertexArrays(1,&s.post_vao);if(s.bloom_program&&s.upsample_program&&s.tonemap_program)return true;if(!s.bloom_program&&!link(a,post_vs,down_fs,s.bloom_program,e))return false;if(!s.upsample_program&&!link(a,post_vs,up_fs,s.upsample_program,e))return false;if(!s.tonemap_program&&!link(a,post_vs,tone_fs,s.tonemap_program,e))return false;return true;}

bool ensure_resources(OpenGLESApi&a,ProductionState&s,const RenderFrame&frame,const RenderPipelinePlan&plan,std::string&e){const int w=std::max(1,int(frame.config.width)),h=std::max(1,int(frame.config.height));const bool resize=s.width!=w||s.height!=h||!s.initialized;if(resize){destroy_target(a,s.hdr);for(auto&t:s.bloom)destroy_target(a,t);s.bloom.clear();if(!create_color_fallback(a,w,h,s.hdr,e))return false;int bw=w,bh=h;const int mips=std::max(1,int(std::min<std::uint32_t>(plan.bloom.mip_count,8u)));for(int i=0;i<mips;++i){bw=std::max(1,bw/2);bh=std::max(1,bh/2);Target t{};if(!create_color_fallback(a,bw,bh,t,e))return false;s.bloom.push_back(t);}destroy_target(a,s.shadow);if(plan.features.enabled(RenderFeature::Shadows)&&!frame.lights.empty()&&!create_shadow(a,int(std::max<std::uint32_t>(512,plan.shadows.atlas_size)),s.shadow,e))return false;s.width=w;s.height=h;s.initialized=true;}if((plan.features.enabled(RenderFeature::Atmosphere)||plan.features.enabled(RenderFeature::Ibl))&&!s.atmosphere){auto pixels=environment_rgba(256,128,plan.atmosphere,0.f,false);if(!ensure_texture(a,s.atmosphere,256,128,pixels,e))return false;}if(plan.features.enabled(RenderFeature::Ibl)&&(!s.irradiance||!s.specular)){auto irr=environment_rgba(int(plan.ibl.irradiance_size),int(std::max(1u,plan.ibl.irradiance_size/2)),plan.atmosphere,0.f,true);auto spec=environment_rgba(int(plan.ibl.specular_size),int(std::max(1u,plan.ibl.specular_size/2)),plan.atmosphere,.45f,false);if(!ensure_texture(a,s.irradiance,int(plan.ibl.irradiance_size),int(std::max(1u,plan.ibl.irradiance_size/2)),irr,e))return false;if(!ensure_texture(a,s.specular,int(plan.ibl.specular_size),int(std::max(1u,plan.ibl.specular_size/2)),spec,e))return false;}if(!ensure_post(a,s,e))return false;return true;}

void bind_shadow_cascade(OpenGLESApi&a,GlUInt program,const ShadowSettings&shadow,GlUInt atlas){if(!program||!atlas)return;a.UseProgram(program);a.ActiveTexture(GL_TEXTURE7);a.BindTexture(GL_TEXTURE_2D,atlas);if(auto u=a.GetUniformLocation(program,"u_shadow_map");u>=0)a.Uniform1i(u,7);if(auto u=a.GetUniformLocation(program,"u_shadow_vp");u>=0)a.UniformMatrix4fv(u,1,0,shadow.cascade[0].view_projection.m.data());}

} 

bool OpenGLESApi::advanced_complete()const noexcept{return complete()&&ClearDepthf&&DrawArrays&&GenFramebuffers&&BindFramebuffer&&DeleteFramebuffers&&FramebufferTexture2D&&CheckFramebufferStatus;}

OpenGLESRenderer::~OpenGLESRenderer(){release_production_gles(*this);release();}

void release_production_gles(OpenGLESRenderer&r) noexcept{std::lock_guard<std::mutex>lock(g_mutex);auto it=g_states.find(&r);if(it==g_states.end())return;destroy_state(const_cast<OpenGLESApi&>(r.api()),*it->second);g_states.erase(it);}

GpuSubmitResult submit_production_gles(OpenGLESRenderer&r,const RenderFrame&frame){GpuSubmitResult result{};if(!frame.valid()){result.error="invalid render frame";return result;}if(!r.api().advanced_complete()){result.error="advanced GLES API is incomplete";return result;}std::string error;if(!r.ready()){result.error="base GLES renderer is not initialized";return result;}AdvancedRenderPipeline planner;const auto plan=planner.build(frame);auto&s=state_for(r);if(!ensure_resources(const_cast<OpenGLESApi&>(r.api()),s,frame,plan,error)){result.error=error;return result;}auto&a=const_cast<OpenGLESApi&>(r.api());a.BindFramebuffer(GL_FRAMEBUFFER,0);a.ActiveTexture(GL_TEXTURE8);a.BindTexture(GL_TEXTURE_2D,s.specular?s.specular:s.atmosphere);for(GlUInt p:{r.mobile_program(),r.mobile_skinned_program(),r.mobile_textured_program(),r.mobile_skinned_textured_program()})configure_material_program(a,p,plan.shadows,s,plan.ibl.intensity);if(plan.features.enabled(RenderFeature::Shadows)&&s.shadow.depth&&!frame.lights.empty()){a.BindFramebuffer(GL_FRAMEBUFFER,s.shadow.fbo);a.Enable(GL_DEPTH_TEST);a.DepthFunc(GL_LESS);a.ClearDepthf(1.f);a.Clear(GL_DEPTH_BUFFER_BIT);a.Viewport(0,0,s.shadow.width,s.shadow.height);bind_shadow_cascade(a,r.mobile_program(),plan.shadows,s.shadow.depth);}a.BindFramebuffer(GL_FRAMEBUFFER,s.hdr.fbo);a.Viewport(0,0,s.hdr.width,s.hdr.height);a.Enable(GL_DEPTH_TEST);const auto base=r.submit(frame);if(!base.success){a.BindFramebuffer(GL_FRAMEBUFFER,0);return base;}result=base;if(plan.features.enabled(RenderFeature::Terrain)||plan.features.enabled(RenderFeature::Vegetation)||plan.features.enabled(RenderFeature::Water)){const auto world=render_world_systems(a,frame,plan);if(!world.success){a.BindFramebuffer(GL_FRAMEBUFFER,0);result.error=world.error;return result;}result.draw_calls+=world.draw_calls;result.triangles+=world.triangles;}a.Disable(GL_DEPTH_TEST);if(plan.features.enabled(RenderFeature::Bloom)&&!s.bloom.empty()){a.UseProgram(s.bloom_program);a.BindVertexArray(s.post_vao);for(std::size_t i=0;i<s.bloom.size();++i){Target&t=s.bloom[i];a.BindFramebuffer(GL_FRAMEBUFFER,t.fbo);a.Viewport(0,0,t.width,t.height);a.ActiveTexture(GL_TEXTURE0);a.BindTexture(GL_TEXTURE_2D,i==0?s.hdr.color:s.bloom[i-1].color);a.Uniform1i(a.GetUniformLocation(s.bloom_program,"u_source"),0);a.Uniform2f;a.Uniform1f(a.GetUniformLocation(s.bloom_program,"u_threshold"),plan.bloom.threshold);a.Uniform1f(a.GetUniformLocation(s.bloom_program,"u_knee"),plan.bloom.knee);a.DrawArrays(0x0004,0,3);}a.UseProgram(s.upsample_program);for(std::size_t i=s.bloom.size();i>1;--i){Target&dst=s.bloom[i-2];Target&src=s.bloom[i-1];a.BindFramebuffer(GL_FRAMEBUFFER,dst.fbo);a.Viewport(0,0,dst.width,dst.height);a.ActiveTexture(GL_TEXTURE0);a.BindTexture(GL_TEXTURE_2D,src.color);a.Uniform1i(a.GetUniformLocation(s.upsample_program,"u_source"),0);a.ActiveTexture(GL_TEXTURE1);a.BindTexture(GL_TEXTURE_2D,dst.color);a.Uniform1i(a.GetUniformLocation(s.upsample_program,"u_bloom"),1);a.DrawArrays(0x0004,0,3);}}a.BindFramebuffer(GL_FRAMEBUFFER,0);a.Viewport(0,0,frame.config.width,frame.config.height);a.UseProgram(s.tonemap_program);a.BindVertexArray(s.post_vao);a.ActiveTexture(GL_TEXTURE0);a.BindTexture(GL_TEXTURE_2D,s.hdr.color);a.Uniform1i(a.GetUniformLocation(s.tonemap_program,"u_hdr"),0);a.ActiveTexture(GL_TEXTURE1);a.BindTexture(GL_TEXTURE_2D,s.bloom.empty()?s.hdr.color:s.bloom[0].color);a.Uniform1i(a.GetUniformLocation(s.tonemap_program,"u_bloom"),1);a.Uniform1f(a.GetUniformLocation(s.tonemap_program,"u_exposure"),plan.hdr.exposure_ev);a.Uniform1f(a.GetUniformLocation(s.tonemap_program,"u_bloom_intensity"),plan.bloom.intensity);a.Uniform1f(a.GetUniformLocation(s.tonemap_program,"u_gamma"),plan.hdr.gamma);a.Uniform1f(a.GetUniformLocation(s.tonemap_program,"u_white_point"),plan.hdr.white_point);a.DrawArrays(0x0004,0,3);a.BindVertexArray(0);result.success=true;return result;}

GpuSubmitResult OpenGLESRenderer::submit_advanced(const RenderFrame&frame){return submit_production_gles(*this,frame);}
}
